"""Create a separate merge-aware citation notebook. Does not open the checkpoint or call APIs.
Usage: python patch_citation_merges_v3.py notebooks/05_yearly_citations_fixed.ipynb
"""
from pathlib import Path
import ast
import json
import sys

EXTENSION = '\n# MERGE_AUDIT_V3_EXTENSION: staged re-audit before changing the locked plan.\n_MA3_ORIGINAL_RESOLVE = resolve_targets\n_MA3_ORIGINAL_PLAN = canonical_plan\n_MA3_ORIGINAL_VALIDATE = validate_page\n_MA3_POLICY = \'response_merge_reaudit_v3\'\n\ndef _ma3_pairs(body):\n    pairs = {}\n    entries = body.get(\'meta\', {}).get(\'merged_ids\', [])\n    if entries is None:\n        entries = []\n    if not isinstance(entries, list):\n        raise StopCollection(\'Malformed merged_ids metadata; checkpoint preserved.\')\n    for entry in entries:\n        if not isinstance(entry, dict):\n            raise StopCollection(\'Malformed merge entry.\')\n        old, new = nid(entry.get(\'id\')), nid(entry.get(\'merge_into_id\'))\n        if not old or not new or (old in pairs and pairs[old] != new):\n            raise StopCollection(\'Invalid/conflicting merge metadata.\')\n        pairs[old] = new\n    return pairs\n\ndef _ma3_follow(value, aliases):\n    current, seen = nid(value), set()\n    if not current:\n        raise RuntimeError(\'Invalid work ID in alias mapping.\')\n    while current in aliases and aliases[current] != current:\n        if current in seen or not nid(aliases[current]):\n            raise RuntimeError(\'Invalid/cyclic alias mapping; no plan migration.\')\n        seen.add(current)\n        current = aliases[current]\n    return current\n\ndef _ma3_init():\n    if conn.in_transaction:\n        raise RuntimeError(\'Unexpected open transaction before merge-audit setup.\')\n    key = _MA3_POLICY + \'_backup\'\n    if not conn.execute(\'SELECT 1 FROM metadata WHERE key=?\', (key,)).fetchone():\n        name = \'citation_collection_before_merge_audit_v3_\' + datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\') + \'.sqlite\'\n        backup = sqlite3.connect(DB_PATH.with_name(name))\n        try:\n            conn.backup(backup)\n        finally:\n            backup.close()\n        with conn:\n            conn.execute(\'INSERT INTO metadata VALUES(?,?)\', (key, name))\n    conn.executescript("""\n        CREATE TABLE IF NOT EXISTS merge_reaudit_v3(\n            old_id TEXT PRIMARY KEY,canonical_id TEXT,status TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS merge_evidence_v3(\n            old_id TEXT PRIMARY KEY,canonical_id TEXT NOT NULL,checked_at TEXT NOT NULL);\n    """)\n\ndef resolve_targets(targets):\n    _MA3_ORIGINAL_RESOLVE(targets)\n    _ma3_init()\n    targets = set(targets)\n    rows = {r[\'old_id\']: dict(r) for r in conn.execute(\'SELECT * FROM work_aliases_v2\')}\n    # Existing 404 gaps stay explicit; do not spend another single-ID lookup on each.\n    required = sorted(w for w in targets if rows[w][\'status\'] == \'resolved\')\n    done = {r[\'old_id\'] for r in conn.execute(\'SELECT old_id FROM merge_reaudit_v3\')}\n    pending = [w for w in required if w not in done]\n    print(\'Merge-aware re-audit:\', len(required) - len(pending), \'/\', len(required), \'resolved target IDs checked.\')\n    for start in range(0, len(pending), BATCH_SIZE):\n        batch = pending[start:start + BATCH_SIZE]\n        body = request_json(\'works\', {\n            \'filter\': \'ids.openalex:\' + \'|\'.join(batch), \'select\': \'id\',\n            \'per_page\': PER_PAGE, \'corpus\': CORPUS})\n        results, count = body.get(\'results\'), body.get(\'meta\', {}).get(\'count\')\n        if not isinstance(results, list) or isinstance(count, bool) or not isinstance(count, int) or count != len(results) or not 0 <= count <= len(batch):\n            raise StopCollection(\'Incomplete ID re-audit batch; no aliases guessed.\')\n        returned = [nid(w.get(\'id\')) if isinstance(w, dict) else None for w in results]\n        if any(w is None for w in returned) or len(returned) != len(set(returned)):\n            raise StopCollection(\'Invalid ID re-audit result.\')\n        merges = _ma3_pairs(body)\n        staged = []\n        for old in batch:\n            if old in merges:\n                current = _ma3_follow(old, merges)\n                status = \'resolved\'\n            elif old in returned:\n                current, status = old, \'resolved\'\n            else:\n                one = request_json(\'works/\' + old, {\'corpus\': CORPUS}, allow_404=True)\n                current = nid(one.get(\'id\')) if one is not None else None\n                if one is not None and not current:\n                    raise StopCollection(\'Invalid single-work re-audit result.\')\n                status = \'resolved\' if current else \'unresolved_404\'\n            staged.append((old, current, status))\n        with conn:\n            for old, new in merges.items():\n                prior = conn.execute(\'SELECT canonical_id FROM merge_evidence_v3 WHERE old_id=?\', (old,)).fetchone()\n                if prior and prior[\'canonical_id\'] != new:\n                    raise StopCollection(\'Merge evidence changed during re-audit; review required.\')\n                conn.execute(\'INSERT OR REPLACE INTO merge_evidence_v3 VALUES(?,?,?)\', (old, new, now()))\n            conn.executemany(\'INSERT INTO merge_reaudit_v3 VALUES(?,?,?)\', staged)\n        if (start // BATCH_SIZE + 1) % 100 == 0:\n            print(\'Additional merge-audit batches saved:\', start // BATCH_SIZE + 1)\n    print(\'Merge-aware re-audit complete. Planning checks follow.\')\n\ndef _ma3_migrate_if_ready():\n    if not conn.execute("SELECT 1 FROM sqlite_master WHERE type=\'table\' AND name=\'merge_reaudit_v3\'").fetchone():\n        return\n    raw, _, ready = raw_portfolios()\n    if not ready:\n        return\n    targets = set().union(*raw.values())\n    rows = {r[\'old_id\']: dict(r) for r in conn.execute(\'SELECT * FROM work_aliases_v2\')}\n    staged = {r[\'old_id\']: dict(r) for r in conn.execute(\'SELECT * FROM merge_reaudit_v3\')}\n    if any(rows.get(w, {}).get(\'status\') not in (\'resolved\', \'unresolved_404\') for w in targets):\n        return\n    if any(w not in staged for w in targets if rows[w][\'status\'] == \'resolved\'):\n        return\n    if conn.execute(\'SELECT 1 FROM metadata WHERE key=?\', (_MA3_POLICY + \'_applied\',)).fetchone():\n        return\n    candidates = {w: r[\'canonical_id\'] for w, r in rows.items() if r[\'status\'] == \'resolved\'}\n    statuses = {w: r[\'status\'] for w, r in rows.items()}\n    for old, row in staged.items():\n        statuses[old] = row[\'status\']\n        if row[\'status\'] == \'resolved\':\n            candidates[old] = row[\'canonical_id\']\n        else:\n            candidates.pop(old, None)\n    for r in conn.execute(\'SELECT old_id,canonical_id FROM merge_evidence_v3\'):\n        candidates[r[\'old_id\']] = r[\'canonical_id\']\n        statuses[r[\'old_id\']] = \'resolved\'\n    for old in candidates:\n        _ma3_follow(old, candidates)\n    mapping = {aid: {_ma3_follow(w, candidates) for w in works if statuses.get(w) == \'resolved\'} for aid, works in raw.items()}\n    fingerprint = stable_hash(sorted((a, sorted(ws)) for a, ws in mapping.items()))\n    desired = {}\n    all_targets = sorted(set().union(*mapping.values()))\n    for start in range(0, len(all_targets), BATCH_SIZE):\n        payload = {\'targets\': all_targets[start:start+BATCH_SIZE], \'year_lo\': WINDOW_LO, \'year_hi\': WINDOW_HI, \'alias_policy\': ALIAS_POLICY}\n        tid = stable_hash({\'kind\': \'citations\', \'payload\': payload, \'corpus\': CORPUS})\n        desired[tid] = payload\n    old_tasks = {r[\'id\']: dict(r) for r in conn.execute("SELECT * FROM tasks WHERE kind=\'citations\'")}\n    if any(tid in old_tasks and old_tasks[tid][\'status\'] == \'superseded\' for tid in desired):\n        raise StopCollection(\'Revised plan would reactivate a superseded task; review needed.\')\n    if any(tid in desired and r[\'status\'] == \'blocked\' for tid, r in old_tasks.items()):\n        raise StopCollection(\'An unchanged desired batch is blocked; review before migration.\')\n    old_hash = conn.execute("SELECT value FROM metadata WHERE key=\'canonical_target_plan_hash_v2\'").fetchone()\n    # Back up the exact pre-migration checkpoint, including staged audit evidence.\n    name = \'citation_collection_before_merge_plan_v3_\' + datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\') + \'.sqlite\'\n    if conn.in_transaction:\n        raise RuntimeError(\'Unexpected transaction before plan migration.\')\n    backup = sqlite3.connect(DB_PATH.with_name(name))\n    try:\n        conn.backup(backup)\n    finally:\n        backup.close()\n    record = {\'at\': now(), \'backup\': name, \'old_hash\': old_hash[\'value\'] if old_hash else None, \'new_hash\': fingerprint, \'desired_batches\': len(desired), \'staged_targets\': len(staged)}\n    with conn:\n        for old, row in staged.items():\n            conn.execute(\'INSERT OR REPLACE INTO work_aliases_v2 VALUES(?,?,?,?,?)\', (old, row[\'canonical_id\'], row[\'status\'], _MA3_POLICY, now()))\n        for r in conn.execute(\'SELECT old_id,canonical_id FROM merge_evidence_v3\').fetchall():\n            conn.execute(\'INSERT OR REPLACE INTO work_aliases_v2 VALUES(?,?,?,?,?)\', (r[\'old_id\'], r[\'canonical_id\'], \'resolved\', \'response_merged_ids_v3\', now()))\n        for tid in old_tasks:\n            if tid not in desired:\n                conn.execute("UPDATE tasks SET status=\'superseded\' WHERE id=?", (tid,))\n        for tid, payload in desired.items():\n            conn.execute(\'INSERT OR IGNORE INTO tasks(id,kind,payload,status) VALUES(?,?,?,?)\', (tid, \'citations\', json.dumps(payload, sort_keys=True), \'pending\'))\n        conn.execute(\'INSERT OR REPLACE INTO metadata VALUES(?,?)\', (\'canonical_target_plan_hash_v2\', fingerprint))\n        conn.execute(\'INSERT INTO metadata VALUES(?,?)\', (_MA3_POLICY + \'_applied\', json.dumps(record, sort_keys=True)))\n        conn.execute(\'DELETE FROM active_citation_tasks_v2\')\n        conn.executemany(\'INSERT INTO active_citation_tasks_v2 VALUES(?)\', [(tid,) for tid in desired])\n    reload_aliases()\n    print(\'Merge-aware plan migration recorded; old evidence preserved. Batches:\', len(desired))\n\ndef canonical_plan():\n    _ma3_migrate_if_ready()\n    return _MA3_ORIGINAL_PLAN()\n\ndef validate_page(task, body):\n    if task[\'kind\'] == \'citations\':\n        merges = _ma3_pairs(body)\n        if any(canonical(old) != canonical(new) for old, new in merges.items()):\n            # Preserve the evidence, not credentials or full API responses.\n            key = \'late_merge_evidence_v3_\' + task[\'id\']\n            with conn:\n                conn.execute(\'INSERT OR REPLACE INTO metadata VALUES(?,?)\', (key, json.dumps({\'at\': now(), \'merges\': merges}, sort_keys=True)))\n            raise BadPage(\'new_merge_after_plan_lock_requires_review\')\n    return _MA3_ORIGINAL_VALIDATE(task, body)\n'

def patch(source):
    source = Path(source)
    nb = json.loads(source.read_text(encoding='utf-8'))
    matches = []
    names = set()
    for index, cell in enumerate(nb.get('cells', [])):
        if cell.get('cell_type') != 'code':
            continue
        text = cell.get('source', '')
        text = ''.join(text) if isinstance(text, list) else text
        if 'MERGE_AUDIT_V3_EXTENSION' in text:
            raise RuntimeError('This notebook is already patched.')
        tree = ast.parse(text)
        for node in tree.body:
            if isinstance(node, ast.FunctionDef):
                names.add(node.name)
                if node.name == 'canonical_plan':
                    matches.append((index, text, node.end_lineno))
    required = {'resolve_targets', 'canonical_plan', 'validate_page', 'reload_aliases', 'raw_portfolios', 'request_json'}
    if required - names or len(matches) != 1:
        raise RuntimeError('Unexpected notebook layout; nothing written. Missing: ' + repr(required - names))
    index, text, end = matches[0]
    lines = text.splitlines(keepends=True)
    prefix, suffix = ''.join(lines[:end]), ''.join(lines[end:])
    nb['cells'][index]['source'] = prefix + '\n\n' + EXTENSION + '\n\n' + suffix
    nb['cells'].insert(0, {
        'cell_type': 'markdown', 'metadata': {},
        'source': '# Merge-aware target re-audit (v3)\n\n'
        'Creates local checkpoint backups, stages a fresh audit of previously resolved raw target IDs, '
        'and migrates the locked citation plan once the audit finishes. Existing 404 gaps remain explicit. '
        'Run only this collector against the checkpoint. Request caps still apply. '
        'Future new merges stop for review; they are not silently mixed into a locked plan.\n'
    })
    for cell in nb['cells']:
        if cell.get('cell_type') == 'code':
            cell['outputs'] = []
            cell['execution_count'] = None
            text = cell.get('source', '')
            ast.parse(''.join(text) if isinstance(text, list) else text)
    nb.get('metadata', {}).pop('widgets', None)
    destination = source.with_name('05_yearly_citations_mergeaware_v3.ipynb')
    if destination.exists():
        raise FileExistsError('Destination already exists; refusing to overwrite it.')
    destination.write_text(json.dumps(nb, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')
    print('Created:', destination)
    print('Original notebook and checkpoint were not modified.')
    return destination

if __name__ == '__main__':
    if len(sys.argv) != 2:
        raise SystemExit('Usage: python patch_citation_merges_v3.py PATH_TO_FIXED_NOTEBOOK')
    patch(sys.argv[1])
